import base64, os
PKG='app/modules/core/shared/models'
FILES={'users': '', 'clients': '', 'projects': '', 'deliverables': '', 'status_logs': '', 'submissions': '', 'flags': '', 'notes': '', 'notifications': '', 'activity': '', 'blog': '', 'feedback': '', 'wiki': '', 'achievements': ''}
for name,b64 in FILES.items():
    open(os.path.join(PKG,name+'.py'),'wb').write(base64.b64decode(b64))
    print('wrote', name+'.py')
print('done', len(FILES), 'files')
